INSERT INTO task_types (task_type, description) VALUES
    ('WORD_COUNT',        'Generates a text corpus and counts word frequencies (hash-map heavy, memory + CPU)'),
    ('PRIME_COUNT',       'Sieve of Eratosthenes - counts primes up to N (CPU + memory bandwidth)'),
    ('MATRIX_MULTIPLY',   'Dense NxN matrix multiplication (pure CPU / floating point)'),
    ('CHECKSUM',          'Streams a large generated buffer through an FNV-1a hash (pure CPU)'),
    ('CPU_BURN',          'Spins on integer arithmetic for scale x 100 ms of real CPU time (short, tunable load)'),
    ('BLOCK_WORD_COUNT',  'MapReduce MAP: reads a distributed block from the Worker disk, counts words, partitions by hash'),
    ('BLOCK_CHECKSUM',    'Reads a distributed block from the Worker disk and returns its SHA-256'),
    ('REDUCE_WORD_COUNT', 'MapReduce REDUCE: merges the word counts of one hash partition')
INSERT INTO scheduler_config (key, value) VALUES ('policy', 'RESOURCE_AWARE')
