-- Static reference data only. NO fake workers, metrics or tasks are seeded:
-- everything in the other tables is generated by the running system.
-- Idempotent.

CREATE TABLE IF NOT EXISTS task_types (
    task_type   VARCHAR(64) PRIMARY KEY,
    description TEXT NOT NULL
);

ON CONFLICT (task_type) DO UPDATE SET description = EXCLUDED.description;

ON CONFLICT (key) DO NOTHING;
